-- Fremdschlüssel von anwesenheit und anwesenheit_anfrage auf lagertag und tagesabschnitt (#374, Nachtrag zu 0085, #390): Die beiden Tabellen entstehen erst in 0070 und standen in 0085 noch nicht zur Verfügung. Zusammengesetzt mit lager_id: ein Feld kann nie auf einen Tag oder Abschnitt eines anderen Lagers zeigen. ON DELETE CASCADE: Fällt ein Tag oder Abschnitt endgültig weg, gehen die Einträge dafür mit.
-- Vorher entfernt die Migration Einträge, deren Tag oder Abschnitt es im Lager nicht gibt (vor dieser Migration prüfte niemand die IDs); auf einer Datenbank ohne solche Zeilen ändert das nichts.
-- Rückweg (Migrationen laufen nur vorwärts): drizzle/rueckweg/0095_lager_anwesenheit_zeitplan.sql, als Besitzer der Datenbank in einer Transaktion: psql -1 -f rueckweg/0095_lager_anwesenheit_zeitplan.sql
--   Entfernt nur die Fremdschlüssel und den Index; gelöschte Einträge kommen nicht zurück.
DELETE FROM "anwesenheit" a WHERE NOT EXISTS (SELECT 1 FROM "lagertag" t WHERE t."lager_id" = a."lager_id" AND t."id" = a."lagertag_id") OR NOT EXISTS (SELECT 1 FROM "tagesabschnitt" t WHERE t."lager_id" = a."lager_id" AND t."id" = a."tagesabschnitt_id");--> statement-breakpoint
DELETE FROM "anwesenheit_anfrage" a WHERE NOT EXISTS (SELECT 1 FROM "lagertag" t WHERE t."lager_id" = a."lager_id" AND t."id" = a."lagertag_id") OR NOT EXISTS (SELECT 1 FROM "tagesabschnitt" t WHERE t."lager_id" = a."lager_id" AND t."id" = a."tagesabschnitt_id");--> statement-breakpoint
ALTER TABLE "anwesenheit" ADD CONSTRAINT "anwesenheit_lagertag_fk" FOREIGN KEY ("lager_id","lagertag_id") REFERENCES "public"."lagertag"("lager_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "anwesenheit" ADD CONSTRAINT "anwesenheit_abschnitt_fk" FOREIGN KEY ("lager_id","tagesabschnitt_id") REFERENCES "public"."tagesabschnitt"("lager_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "anwesenheit_anfrage" ADD CONSTRAINT "anwesenheit_anfrage_lagertag_fk" FOREIGN KEY ("lager_id","lagertag_id") REFERENCES "public"."lagertag"("lager_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "anwesenheit_anfrage" ADD CONSTRAINT "anwesenheit_anfrage_abschnitt_fk" FOREIGN KEY ("lager_id","tagesabschnitt_id") REFERENCES "public"."tagesabschnitt"("lager_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "anwesenheit_abschnitt_idx" ON "anwesenheit" USING btree ("lager_id","tagesabschnitt_id");
